<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\AcademicSetting; use App\Models\CourseClass; use App\Models\Department; use App\Models\Program; use App\Models\User; use Illuminate\Http\Request;
class AcademicController extends Controller { public function index(){return view('admin.academic.index',['departments'=>Department::with('programs')->get(),'settings'=>AcademicSetting::latest()->get(),'classes'=>CourseClass::with('lecturer')->latest()->paginate(15),'lecturers'=>User::where('role','lecturer')->get()]);} public function storeDepartment(Request $r){Department::create($r->validate(['name'=>['required','max:120','unique:departments,name'],'code'=>['required','max:30','unique:departments,code']]));return back()->with('status','Department added.');} public function storeProgram(Request $r){Program::create($r->validate(['department_id'=>['required','exists:departments,id'],'name'=>['required','max:160'],'level'=>['required','in:Certificate,Diploma,Degree,Masters,PhD']]));return back()->with('status','Programme added.');} public function storeSetting(Request $r){$data=$r->validate(['academic_year'=>['required','regex:/^\\d{4}\\/\\d{4}$/'],'semester'=>['required','max:30'],'is_current'=>['nullable','boolean']]);if($r->boolean('is_current')) AcademicSetting::query()->update(['is_current'=>false]);AcademicSetting::create([...$data,'is_current'=>$r->boolean('is_current')]);return back()->with('status','Academic period saved.');} public function updateClass(Request $r,CourseClass $courseClass){$data=$r->validate(['lecturer_id'=>['required','exists:users,id'],'academic_year'=>['required','max:20'],'semester'=>['required','max:30']]);$lecturer=User::findOrFail($data['lecturer_id']);abort_unless($lecturer->role==='lecturer',422);$courseClass->update($data);return back()->with('status','Class reassigned.');} public function destroyClass(CourseClass $courseClass){$courseClass->delete();return back()->with('status','Class deleted.');} }
